powerpagecomponent.content:
{
  "source": "{% assign headingText = section.hit_headingtext | default:'' | strip %}
{% assign introText = section.hit_introtext | default:'' | strip %}

{% assign widthClass = 'layout--medium' %}
{% assign alignClass = 'layout--centre' %}

{% if slots and slots.size > 0 %}
    {% assign slot1 = slots | where: "hit_slotindex", 1 | first %}

    {% if slot1 %}

        {% assign widthValue = slot1.hit_contentwidth.value | default: '' | append:'' %}
        {% assign alignValue = slot1.hit_contenthalign.value | default: '' | append:'' %}

        {% comment %}
        Content Width
        Narrow = 815390000
        Medium = 815390001
        Wide   = 815390002
        Full   = 815390003
        {% endcomment %}

        {% if widthValue == '815390000' %}
            {% assign widthClass = 'layout--narrow' %}
        {% elsif widthValue == '815390001' %}
            {% assign widthClass = 'layout--medium' %}
        {% elsif widthValue == '815390002' %}
            {% assign widthClass = 'layout--wide' %}
        {% elsif widthValue == '815390003' %}
            {% assign widthClass = 'layout--full' %}
        {% endif %}

        {% comment %}
        H-Align
        Left   = 815390000
        Centre = 815390001
        Right  = 815390002
        {% endcomment %}

        {% if alignValue == '815390000' %}
            {% assign alignClass = 'layout--left' %}
        {% elsif alignValue == '815390001' %}
            {% assign alignClass = 'layout--centre' %}
        {% elsif alignValue == '815390002' %}
            {% assign alignClass = 'layout--right' %}
        {% endif %}

    {% endif %}
{% endif %}


<div class="layout layout-1-col {{ widthClass }} {{ alignClass }}">


    {% if headingText != '' or introText != '' %}

        <div class="hit-section__header">

            {% if headingText != '' %}
                <h2 class="hit-section__title">
                    {{ headingText }}
                </h2>
            {% endif %}

            {% if introText != '' %}
                <div class="hit-section__intro">
                    {{ introText }}
                </div>
            {% endif %}

        </div>

    {% endif %}

    {% if slots and slots.size > 0 %}

        {% assign slot1 = slots | where: "hit_slotindex", 1 | first %}

        {% if slot1 %}

            {% assign templateName = slot1['stype.hit_templatename'] | default:'' | strip | downcase %}

            {% if templateName != '' %}

                {% include templateName  section: section  slot: slot1  debug: debug  galleryParam: galleryParam  galleryOverride: galleryOverride   %}

            {% else %}

                <div style="color:red;">
                    ❌ Slot has no template
                </div>

            {% endif %}

        {% else %}

            <div style="color:red;">
                ❌ Slot index 1 not found
            </div>

        {% endif %}

    {% else %}

        <div style="color:red;">
            ❌ Slots array empty
        </div>

    {% endif %}

</div>"
}
